umb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/10/\",\"title\":\"Chapter Ten: The Opulence of the Absolute\"}],\"url_path\":\"/en/library/bg/10/12-13/\",\"bb\":2582,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/10/11/\",\"title\":\"TEXT 11\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/10/14/\",\"title\":\"TEXT 14\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2916,\"bb\":568252,\"url_path\":\"/en/library/bg/10/12-13/devanagari/\",\"body_final\":\"अर्जुन उवाच
परं ब्रह्म परं धाम पवित्रं परमं भवान् ।
पुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम् ॥ १२ ॥
आहुस्त्वामृषय: सर्वे देवर्षिर्नारदस्तथा ।
असितो देवलो व्यास: स्वयं चैव ब्रवीषि मे ॥ १३ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2917,\"bb\":2583,\"url_path\":\"/en/library/bg/10/12-13/b2583/\",\"body_value\":\"arjuna uvāca
paraṁ brahma paraṁ dhāma
pavitraṁ paramaṁ bhavān
puruṣaṁ śāśvataṁ divyam
ādi-devam ajaṁ vibhum\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2918,\"bb\":2584,\"url_path\":\"/en/library/bg/10/12-13/b2584/\",\"body_value\":\"āhus tvām ṛṣayaḥ sarve
devarṣir nāradas tathā
asito devalo vyāsaḥ
svayaṁ caiva bravīṣi me\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2919,\"bb\":2585,\"url_path\":\"/en/library/bg/10/12-13/b2585/\",\"shadow_value\":\"arjunaḥ uvāca – Arjuna said; param – supreme; brahma – truth; param – supreme; dhāma – sustenance; pavitram – pure; paramam – supreme; bhavān – You; puruṣam – personality; śāśvatam – eternal; divyam – transcendental; ādi-devam – the original Lord; ajam – unborn; vibhum – greatest; āhuḥ – say; tvām – of You; ṛṣayaḥ – sages; sarve – all; deva-ṛṣiḥ – the sage among the demigods; nāradaḥ – Nārada; tathā – also; asitaḥ – Asita; devalaḥ – Devala; vyāsaḥ – Vyāsa; svayam – personally; ca – also; eva – certainly; bravīṣi – You are explaining; me – unto me.\",\"word_for_word_value\":[{\"word\":\"arjunaḥ uvāca\",\"translation\":\"Arjuna said\"},{\"word\":\"param\",\"translation\":\"supreme\"},{\"word\":\"brahma\",\"translation\":\"truth\"},{\"word\":\"param\",\"translation\":\"supreme\"},{\"word\":\"dhāma\",\"translation\":\"sustenance\"},{\"word\":\"pavitram\",\"translation\":\"pure\"},{\"word\":\"paramam\",\"translation\":\"supreme\"},{\"word\":\"bhavān\",\"translation\":\"You\"},{\"word\":\"puruṣam\",\"translation\":\"personality\"},{\"word\":\"śāśvatam\",\"translation\":\"eternal\"},{\"word\":\"divyam\",\"translation\":\"transcendental\"},{\"word\":\"ādi-devam\",\"translation\":\"the original Lord\"},{\"word\":\"ajam\",\"translation\":\"unborn\"},{\"word\":\"vibhum\",\"translation\":\"greatest\"},{\"word\":\"āhuḥ\",\"translation\":\"say\"},{\"word\":\"tvām\",\"translation\":\"of You\"},{\"word\":\"ṛṣayaḥ\",\"translation\":\"sages\"},{\"word\":\"sarve\",\"translation\":\"all\"},{\"word\":\"deva-ṛṣiḥ\",\"translation\":\"the sage among the demigods\"},{\"word\":\"nāradaḥ\",\"translation\":\"Nārada\"},{\"word\":\"tathā\",\"translation\":\"also\"},{\"word\":\"asitaḥ\",\"translation\":\"Asita\"},{\"word\":\"devalaḥ\",\"translation\":\"Devala\"},{\"word\":\"vyāsaḥ\",\"translation\":\"Vyāsa\"},{\"word\":\"svayam\",\"translation\":\"personally\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"bravīṣi\",\"translation\":\"You are explaining\"},{\"word\":\"me\",\"translation\":\"unto me\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2920,\"bb\":2586,\"url_path\":\"/en/library/bg/10/12-13/b2586/\",\"body_value\":\"Arjuna said: You are the Supreme Personality of Godhead, the ultimate abode, the purest, the Absolute Truth. You are the eternal, transcendental, original person, the unborn, the greatest. All the great sages such as Nārada, Asita, Devala and Vyāsa confirm this truth about You, and now You Yourself are declaring it to me.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2921,\"bb\":2587,\"url_path\":\"/en/library/bg/10/12-13/b2587/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2922,\"bb\":2588,\"url_path\":\"/en/library/bg/10/12-13/b2588/\",\"body_value\":\" In the Kena Upaniṣad it is stated that the Supreme Brahman is the rest for everything, and Kṛṣṇa has already explained that everything is resting on Him. The Muṇḍaka Upaniṣad confirms that the Supreme Lord, in whom everything is resting, can be realized only by those who engage constantly in thinking of Him. This constant thinking of Kṛṣṇa is smaraṇam, one of the methods of devotional service. It is only by devotional service to Kṛṣṇa that one can understand his position and get rid of this material body.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2923,\"bb\":2589,\"url_path\":\"/en/library/bg/10/12-13/b2589/\",\"body_value\":\"In the Vedas the Supreme Lord is accepted as the purest of the pure. One who understands that Kṛṣṇa is the purest of the pure can become purified from all sinful activities. One cannot be disinfected from sinful activities unless he surrenders unto the Supreme Lord. Arjuna’s acceptance of Kṛṣṇa as the supreme pure complies with the injunctions of Vedic literature. This is also confirmed by great personalities, of whom Nārada is the chief.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2924,\"bb\":2590,\"url_path\":\"/en/library/bg/10/12-13/b2590/\",\"body_value\":\"Kṛṣṇa is the Supreme Personality of Godhead, and one should always meditate upon Him and enjoy one’s transcendental relationship with Him. He is the supreme existence. He is free from bodily needs, birth and death. Not only does Arjuna confirm this, but all the Vedic literatures, the Purāṇas and histories. In all Vedic literatures Kṛṣṇa is thus described, and the Supreme Lord Himself also says in the Fourth Chapter, “Although I am unborn, I appear on this earth to establish religious principles.” He is the supreme origin; He has no cause, for He is the cause of all causes, and everything is emanating from Him. This perfect knowledge can be had by the grace of the Supreme Lord.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2925,\"bb\":2591,\"url_path\":\"/en/library/bg/10/12-13/b2591/\",\"body_value\":\"Here Arjuna expresses himself through the grace of Kṛṣṇa. If we want to understand Bhagavad-gītā, we should accept the statements in these two verses. This is called the paramparā system, acceptance of the disciplic succession. Unless one is in the disciplic succession, he cannot understand Bhagavad-gītā. It is not possible by so-called academic education. Unfortunately those proud of their academic education, despite so much evidence in Vedic literatures, stick to their obstinate conviction that Kṛṣṇa is an ordinary person.\"}]}],\"short_title\":\"Bg. 10.12-13\",\"medium_title\":\"Bhagavad-gītā As It Is 10.12-13\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"Bhagavad-gītā As It Is\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/10/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/10/\",\"className\":\"text-vb-link\",\"children\":\"Chapter Ten: The Opulence of the Absolute\"}],false]}]]}]}],[\"$\",\"main\",null,{\"children\":[\"$L29\",[\"$\",\"div\",null,{\"children\":[[\"$\",\"$L2a\",null,{\"child\":\"$23:props:children:0:props:children:props:page\",\"hasId\":false,\"isWholePage\":true,\"children\":[\"$\",\"h1\",nul