dren\":[[[\"$\",\"$L20\",\"wfwundefined-0-asitaḥ\",{\"href\":\"/en/search/synonyms/?original=asitaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"asitaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"Asita\"}}],\"; \"]}]\n3c:[\"$\",\"span\",\"wfwundefined-22\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-devalaḥ\",{\"href\":\"/en/search/synonyms/?original=devalaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"devalaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"Devala\"}}],\"; \"]}]\n3d:[\"$\",\"span\",\"wfwundefined-23\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-vyāsaḥ\",{\"href\":\"/en/search/synonyms/?original=vyāsaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"vyāsaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"Vyāsa\"}}],\"; \"]}]\n3e:[\"$\",\"span\",\"wfwundefined-24\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-svayam\",{\"href\":\"/en/search/synonyms/?original=svayam\",\"children\":[\"$\",\"em\",null,{\"children\":\"svayam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"personally\"}}],\"; \"]}]\n3f:[\"$\",\"span\",\"wfwundefined-25\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ca\",{\"href\":\"/en/search/synonyms/?original=ca\",\"children\":[\"$\",\"em\",null,{\"children\":\"ca\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"also\"}}],\"; \"]}"])self.__next_f.push([1,"]\n40:[\"$\",\"span\",\"wfwundefined-26\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-eva\",{\"href\":\"/en/search/synonyms/?original=eva\",\"children\":[\"$\",\"em\",null,{\"children\":\"eva\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"certainly\"}}],\"; \"]}]\n41:[\"$\",\"span\",\"wfwundefined-27\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bravīṣi\",{\"href\":\"/en/search/synonyms/?original=bravīṣi\",\"children\":[\"$\",\"em\",null,{\"children\":\"bravīṣi\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"You are explaining\"}}],\"; \"]}]\n42:[\"$\",\"span\",\"wfwundefined-28\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-me\",{\"href\":\"/en/search/synonyms/?original=me\",\"children\":[\"$\",\"em\",null,{\"children\":\"me\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"unto me\"}}],\".\"]}]\n44:[\"$\",\"$L2a\",\"child-2925\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:4\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Here Arjuna expresses himself through the grace of Kṛṣṇa. If we want to understand Bhagavad-gītā, we should accept the statements in these two verses. This is called the paramparā system, acceptance of the disciplic succession. Unless one is in the disciplic succession, he cannot understand Bhagavad-gītā. It is not possible by so-called academic education. Unfortunately those proud of their academic education, despite so much evidence in Vedic literatures, stick to their obstinate conviction that Kṛṣṇa is an ordinary person.\"}}]}]\n"])(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document);if(b){var d=b.createElement(''script'');d.innerHTML="window.__CF$cv$params={r:''a340589d1d7df501'',t:''MTc4ODIyNDUxMQ==''};var a=document.createElement(''script'');a.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'';document.getElementsByTagName(''head'')[0].appendChild(a);";b.getElementsByTagName(''